    @Test("hingeLoss")
    func test_hingeLoss() throws {
        try withIntegrationState(seed: 32168) {
            let inputs = MLXRandom.normal([4, 3], dtype: .float32, loc: 0.0, scale: 1.0)
            let signs = MLXRandom.bernoulli(0.5, [4, 3])
            let targets = MLX.which(signs, 1.0, -1.0)
            let result = MLXNN.hingeLoss(inputs: inputs, targets: targets)
